<?php
require_once __DIR__ . '/../includes/db.php'; require_admin(); $page_title='Manage Payments'; $payments=$pdo->query('SELECT p.*,i.item_name,u.name AS payer_name FROM payments p INNER JOIN bookings b ON b.booking_id=p.booking_id INNER JOIN items i ON i.item_id=b.item_id INNER JOIN users u ON u.user_id=p.user_id ORDER BY p.created_at DESC')->fetchAll(); require_once __DIR__ . '/../includes/header.php'; require __DIR__ . '/_nav.php';
?>
<h1 class="h3 mb-4">Payments</h1><div class="card shadow-sm"><div class="table-responsive"><table class="table table-hover mb-0"><thead class="table-light"><tr><th class="ps-3">Item / Payer</th><th>Method</th><th>Reference</th><th>Amount</th><th class="pe-3">Status</th></tr></thead><tbody><?php foreach($payments as $payment): ?><tr><td class="ps-3"><?php echo e($payment['item_name']); ?><div class="small text-muted"><?php echo e($payment['payer_name']); ?></div></td><td><?php echo e($payment['payment_method']); ?></td><td class="small"><?php echo e($payment['transaction_reference']); ?></td><td><?php echo e(format_money($payment['amount'])); ?></td><td class="pe-3"><span class="badge text-bg-<?php echo e(status_badge_class($payment['payment_status'])); ?>"><?php echo e($payment['payment_status']); ?></span></td></tr><?php endforeach; ?></tbody></table></div></div><?php require_once __DIR__ . '/../includes/footer.php'; ?>
